import sys

def main():
    data = list(map(int, sys.stdin.read().split()))
    if not data:
        return

    n = data[0]
    dario = 0
    xerxes = 0
    idx = 1

    for _ in range(n):
        d = data[idx]
        x = data[idx + 1]
        idx += 2

        diff = (x - d) % 5
        if diff == 1 or diff == 2:
            dario += 1
        else:
            xerxes += 1

    if dario > xerxes:
        sys.stdout.write("dario\n")
    else:
        sys.stdout.write("xerxes\n")

